\label{Thm2}
Let $d \geq 2$,  $1 < p < q < \infty$, $1 \leq  \theta \leq\ \infty$.   Then for 
$r_1 > 1/p-1/q$

the following estimates hold
\begin{equation}\label{eqno17}
\mathscr{E}_{Q^{{\boldsymbol{\gamma}}}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{q,1}}    \asymp  E_{Q^{{\boldsymbol{\gamma}}}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{q,1}}   \asymp  2^{ -n( r_1 - \frac{1}{p} + \frac{1}{q})} n^{(\nu - 1)(1 - \frac{1}{\theta})}.
\end{equation}

\label{Thm1}
  Let $d \geq 2$, $1 < p < \infty$, $1 \leq \theta \leq \infty$. Then for $r_1 > 0$ it holds
\begin{equation*}              
\mathscr{E}_{Q^{{\boldsymbol{\gamma}}'}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{p,1}}    \asymp  E_{Q^{{\boldsymbol{\gamma}}'}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{p,1}}   \asymp  2^{ -n  r_1} n^{(\nu - 1)(1 - \frac{1}{\theta})}.
\end{equation*}

\label{Thm3}
Let $d \geq 2$,  $p \in \{1, \infty\}$, $1 \leq  \theta \leq \infty$. Then for $r_1 > 0$ it holds
\begin{equation}\label{eqno27}
 E_{Q^{{\boldsymbol{\gamma}}'}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{p,1}}   \asymp  2^{ -n  r_1} n^{(\nu - 1)(1 - \frac{1}{\theta})}.
\end{equation}

One can show that under the conditions of Theorem \ref{Thm3} it holds
\begin{equation}\label{eqno27.gamma}
 E_{Q^{{\boldsymbol{\gamma}}}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{p,1}}   \asymp  2^{ -n  r_1} n^{(d - 1)(1 - \frac{1}{\theta})}.
\end{equation}

