\mathscr{E}_{Q^{{\boldsymbol{\gamma}}'}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{q,1}}    \asymp  E_{Q^{{\boldsymbol{\gamma}}'}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{q,1}}   \asymp  2^{ -n r_1} n^{(\nu - 1)(1 - \frac{1}{\theta})}.
\end{equation}

