\label{summung_up_best_approx}
    Summing up all of the results from Section \ref{sec2:App_shFs}, we get the following statement.

    Let $d\geq 2$, $1\leq \theta\leq \infty$. Then for $r>(1/p-1/q)_+$ it holds
$$
 E_{Q^{{\boldsymbol{\gamma}^*}}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{q,1}} 
  \asymp \mathscr{E}_{Q^{{\boldsymbol{\gamma}}^*}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{q,1}}
 \asymp  2^{ -n \left(  r_1-(\frac{1}{p}-\frac{1}{q})_+\right)} n^{(\mu^*-1)(1 - \frac{1}{\theta})},
$$
    where 
    \begin{itemize}
        \item in the case $1<p<q<\infty$ we put ${\boldsymbol{\gamma}}^* = \boldsymbol{\gamma}$, $\mu^* = \nu$;

        \item in the cases  $1<p=q<\infty$ and $1\leq q <p \leq \infty$ we put
        either ${\boldsymbol{\gamma}}^* = \boldsymbol{\gamma}'$, $\mu^* = \nu$  or ${\boldsymbol{\gamma}}^* = \boldsymbol{\gamma}$, $\mu^* = d$.
\end{itemize}
If $p=q\in \{1, \infty\}$, then 
    $$
     E_{Q^{{\boldsymbol{\gamma}}*}_n} ( B^{\boldsymbol{r}}_{p,\theta})_{B_{p,1}}   \asymp  2^{ -n  r_1} n^{(\mu^* - 1)(1 - \frac{1}{\theta})}
    $$ 
     with 
 either ${\boldsymbol{\gamma}}^* = \boldsymbol{\gamma}'$, $\mu^* = \nu$  or ${\boldsymbol{\gamma}}^* = \boldsymbol{\gamma}$, $\mu^* = d$.

\label{Thm5}
 Let  $ r_1 > 0$   and  $1 \leq \theta \leq \infty$.   Then it holds
\begin{equation*}               
\varepsilon_M ( B^{\boldsymbol{r}}_{\infty,\theta}, B_{1,1}) \gg   M^{ - r_1} (\log^{\nu - 1} M)^{ r_1 + 1 - \frac{1}{\theta}}.
\end{equation*}

In the case $\theta = \infty$, as it was noted above, the estimate was obtained in  \cite{Temlyakov1990}. Therefore,
 we assume that 
 $1\leq \theta <\infty$. Besides, it  is  sufficient  to  consider the  case $\nu = d$.

We will use some relations from  the proof of Theorem 2.2 in \cite{Temlyakov1990}, in particular, the estimate
\begin{equation}\label{eqno41}
\varepsilon_M ( T'(Q'_n)_\infty \, 2^{-n r_1}, L_2) \gg   M^{ - r_1} (\log^{d - 1} M)^{ r_1 +  \frac{1}{2}},
\end{equation}
where $M = |Q^{'}_n| \asymp 2^n n^{d - 1}$.

Since the  embedding
$$
T'(Q'_n)_{\infty}\, 2^{-n r_1} \subset C_7 H^{\boldsymbol{r}}_{\infty}, \quad C_7 > 0,
$$
is true,  for   $f \in T'(Q'_n)_{\infty} \, 2^{-n r_1}$
it holds $\|A_{\boldsymbol{s}}(f)\|_{\infty} \ll 2^{-({\boldsymbol{s}},r)}$, $s \in  \Omega_n$
(see (\ref{norm_via_A_s_infty})).

Therefore,  for  $f \in  T'(Q'_n)_{\infty} \, 2^{-n r_1}$ from (\ref{norm_via_A_s_notinfty}) and (\ref{norm_As_1}) we  get
\begin{align*}
\|f\|_{B^{\boldsymbol{r}}_{\infty, \theta}} & \asymp   \Bigg(  \sum\limits_{{\boldsymbol{s}} \in \Omega_n}  2^{({\boldsymbol{s}},{\boldsymbol{r}})\theta} \|A_{\boldsymbol{s}}(f)\| ^{\theta}_{\infty} \Bigg)^{\frac{1}{\theta}}
\ll \Bigg(  \sum\limits_{{\boldsymbol{s}} \in \Omega_n}  2^{({\boldsymbol{s}},{\boldsymbol{r}})\theta} \|A_{\boldsymbol{s}}\|^{\theta}_1\,\,  \|f\|^{\theta}_{\infty} \Bigg)^{\frac{1}{\theta}}
\\
&  \ll \Bigg(  \sum\limits_{{\boldsymbol{s}} \in \Omega_n}  2^{({\boldsymbol{s}},{\boldsymbol{r}})\theta}\,\, \|f\|^{\theta}_{\infty} \Bigg)^{\frac{1}{\theta}} \ll   \Bigg(  \sum\limits_{{\boldsymbol{s}} \in \Omega_n}  1 \Bigg)^{\frac{1}{\theta}} \asymp n^{\frac{d -1}{\theta}},
\end{align*}
and thus
\begin{equation}\label{eqno42}
T'(Q'_n)_{\infty} \, 2^{-n r_1} n^{ - \frac{d -1}{\theta}} \subset  C_8 B^{\boldsymbol{r}}_{\infty, \theta}, \quad 1 \leq \theta < \infty, \quad  C_8 > 0. \end{equation}
Hence, according  to (\ref{eqno41}), in view of $M \asymp 2^n n^{d - 1}$, i.e., $n \asymp \log M$,  we  can  write
\begin{align}
\varepsilon_M ( T'(Q'_n)_{\infty}\,\,  2^{-n r_1}\,\,  n^{ - \frac{d -1}{\theta}}, L_2) &



\gg M^{ - r_1} (\log^{d - 1} M)^{ r_1 +  \frac{1}{2} - \frac{1}{\theta}}
\nonumber
\\
& 
\asymp 2^{-n r_1} n^{(d - 1)(\frac{1}{2} - \frac{1}{\theta})}.   \label{eqno43}
\end{align}


Let $A$   be  a  compact  set  and  $M_{\varepsilon}(A, \mathscr{X})$    be   the  maximum  number  of  points $x^j \in A$  such  that  $\|x^i - x^j\|_{\mathscr{X}} > \varepsilon$, $i \neq j$; $N_{\varepsilon}(A, \mathscr{X})$  be  a  number  defined  by  the formula  (\ref{eqno39}).

It is well known that 
\begin{equation}\label{eqno44}
N_\varepsilon (A, \mathscr{X}) \leq M_\varepsilon (A, \mathscr{X}) \leq N_{\varepsilon/2} (A, \mathscr{X}).
\end{equation}
The relations (\ref{eqno43}) and (\ref{eqno44}) yield that in   $T'(Q'_n)_{\infty}\,  2^{-n r_1} n^{ - \frac{d -1}{\theta}}$  there exist $2^M$  functions  $\{ f_j \}^{2^M}_{j=1}$  such that for $i \neq j$  it holds
\begin{equation}\label{eqno45}
\|f_i - f_j\|_2 \gg 2^{-n r_1} n^{(d - 1)(\frac{1}{2} - \frac{1}{\theta})}.
\end{equation}
Further

we  

show that
\begin{equation}\label{eqno46}
\|f_i - f_j\|_{B_{1,1}} \gg 2^{-n r_1} n^{(d - 1)(1 - \frac{1}{\theta})}.
\end{equation}

Indeed, taking into account (\ref{eqno45}) and the definition (\ref{norm_Bq1_via_As}) of the norm in the space $B_{1,1}$, for $f \in T'(Q'_n)_{\infty}$ we obtain
\begin{align}
n^{d -1} \ll \|f\|^2_2 & = \sum\limits_{{\boldsymbol{s}} \in \Omega_n} \, \| \sum\limits_{\|{\boldsymbol{s}} - {\boldsymbol{s}}'\|_{\infty} \leq 1} A_{{\boldsymbol{s}}'}(f) \|^2_2 \leq
  \sum\limits_{{\boldsymbol{s}} \in \Omega_n}  \sum\limits_{\|{\boldsymbol{s}} - {\boldsymbol{s}}'\|_{\infty} \leq 1} \|A_{{\boldsymbol{s}}'}(f) \|^2_2
\nonumber\\
& \leq  \sum\limits_{{\boldsymbol{s}} \in \Omega_n}  \sum\limits_{\|{\boldsymbol{s}} - {\boldsymbol{s}}'\|_{\infty} \leq 1} \|A_{{\boldsymbol{s}}'}(f) \|_1 \, \|A_{{\boldsymbol{s}}'}(f)\|_\infty
\nonumber\\
& \leq  \mathop{\max_{{\boldsymbol{s}} \in \Omega_n}} \limits_{\|{\boldsymbol{s}} - {\boldsymbol{s}}'\|_{\infty} \leq 1} \|A_{{\boldsymbol{s}}'}(f) \|_\infty  \sum\limits_{{\boldsymbol{s}}\in \mathbb{N}^d} \|A_{{\boldsymbol{s}}}(f) \|_1 \ll \|f\|_{B_{1,1}}.
\label{eqno47}
\end{align}
Combining (\ref{eqno45}) with (\ref{eqno47}), we get (\ref{eqno46}).

Hence, from  (\ref{eqno42}) and (\ref{eqno46}), in view of $M \asymp 2^n n^{d - 1}$, we obtain the estimate
\begin{align*}
\varepsilon_M ( B^{\boldsymbol{r}}_{\infty,\theta}, B_{1,1})& \gg
\varepsilon_M (T'(Q'_n)_{\infty} \, 2^{-n r_1} n^{ - \frac{d -1}{\theta}}, B_{1,1})


\gg   

2^{-n r_1} n^{(d - 1)(1 - \frac{1}{\theta})}
\\
&    \asymp     M^{ - r_1} (\log^{d - 1} M)^{ r_1 + 1 - \frac{1}{\theta}}.
\end{align*}

Theorem \ref{Thm5} is proved.

\label{Thm8}
Let  $d \geq 2$, $r_1 > 0$, $1 \leq q \leq  p \leq \infty$, $1 \leq \theta \leq \infty$.  Then  it holds
\begin{equation}\label{eqno57}
\varepsilon_M ( B^{\boldsymbol{r}}_{p,\theta},  B_{q,1}) \asymp  d_M ( B^{\boldsymbol{r}}_{p, \theta}, B_{q,1})   \asymp  \lambda_M ( B^{\boldsymbol{r}}_{p, \theta}, B_{q,1})  \asymp
  M^{ - r_1} (\log^{\nu - 1} M)^{ r_1 + 1 - \frac{1}{\theta}}.
\end{equation}

