\varepsilon_M ( B^{\boldsymbol{r}}_{p,\theta},  L_p) \asymp  d_M ( B^{\boldsymbol{r}}_{p, \theta}, L_p) 
\asymp  \lambda_M ( B^{\boldsymbol{r}}_{p, \theta}, L_p)
\asymp 
M^{ - r_1} (\log^{\nu - 1} M)^{ r_1 +  \frac{1}{2} - \frac{1}{\theta}}.
\end{equation}

